-- Currency dictionary, sourced from https://api.frankfurter.dev/v2/currencies on 2026-05-05.
-- `rate_source` is a free-form label of where conversion rates for this currency are pulled
-- from. Currently only one source ('frankfurter'); future extensions might add 'cbr',
-- 'binance', etc. NULL means "no automatic rate feed wired up for this currency".
CREATE TABLE currencies (
    code        TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    symbol      TEXT NOT NULL,
    rate_source TEXT
);

